window.FTA_TOUR = {"slug":"outersect-single-breath","title":"Single Breath","artist":"Outersect","bpm":75,"key":"D Dorian","seconds":59.6,"group":"influences","how":"After \"To Take a Single Conscious Breath Without Discursive Thought\": psybient as meditation, with a round dub bass, a soft broken beat, a breathy flute answered by FM sitar, and long feedback echoes. Written from the approach and the title, not from the record.","trick":"The whole arrangement breathes: everything swells over an in-breath of four beats, holds for four, and lets go over eight, the count of a slow breathing practice.","stops":[{"t":0,"label":"Breathing in","text":"Breathing in: a pad that rises and falls with the breath."},{"t":12.8,"label":"The flute","text":"A breathy flute carries a slow line."},{"t":19.2,"label":"Sitar answers","text":"An FM sitar answers it, buzzing at the attack the way a jawari bridge does."},{"t":38.4,"label":"The last breath","text":"The last full breath, with the dub delay feeding back."},{"t":51.2,"label":"Out","text":"Out: the breath lets go."}],"checks":{"lufs":-14.0,"tp":-1.6,"clicks":0,"sha":"C90EFF60FA9DE6CE"},"gram":{"rows":72,"cols":596,"lo":"C1","fps":10,"b64":""},"videos":[{"t":0,"clip":"video/way-of-water.mp4","label":"The Way of Water","page":"/way-of-water.html"},{"t":12.8,"clip":"video/navier-stokes-demo.mp4","label":"2D fluid simulation","page":"/navier-stokes-demo.html"},{"t":19.2,"clip":"video/votes-as-rain.mp4","label":"Votes as rain","page":"/votes-as-rain.html"},{"t":38.4,"clip":"video/way-of-water.mp4","label":"The Way of Water","page":"/way-of-water.html"},{"t":51.2,"clip":"video/navier-stokes-demo.mp4","label":"2D fluid simulation","page":"/navier-stokes-demo.html"}]};
